const r = $json.resumo || {};
const brl = v => Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const MES=['','Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const CAT={Groceries:'Mercado','Food delivery':'Delivery','Eating out':'Restaurante','Food and drinks':'Alimentação',Housing:'Moradia','Digital services':'Serviços digitais','Gas stations':'Posto de gasolina',Pharmacy:'Farmácia',Shopping:'Compras',Transfers:'Transferências',Services:'Serviços',Healthcare:'Saúde',Electricity:'Energia',Transportation:'Transporte',Education:'Educação',Insurance:'Seguro',Automotive:'Automotivo',Internet:'Internet',Telecommunications:'Telecom',Gaming:'Games','Pet supplies and vet':'Pet e veterinário',Pets:'Pet','Taxi and ride-hailing':'Táxi e apps','Public transportation':'Transporte público',Clothing:'Roupas',Travel:'Viagem','Water and sewage':'Água',Water:'Água'};
const clean = s => String(s||'').replace(/[*_`\[\]]/g,'');
const tc = c => CAT[c]||c;
const [y,m] = String(r.mes||'0000-00').split('-');
const receita=Number(r.receita||0), despesa=Number(r.despesa||0), saldo=receita-despesa;
const dAnt = Number(r.despesa_ant)>50 ? Math.round((despesa-Number(r.despesa_ant))/Number(r.despesa_ant)*100) : null;
const cmp = dAnt==null ? '' : ` (${dAnt>=0?'+':''}${dAnt}% vs mês anterior)`;
let txt = `📊 *Fechamento de ${MES[+m]||''} ${y}*\n\n`;
txt += `💰 Receita: ${brl(receita)}\n`;
txt += `💸 Despesa: ${brl(despesa)}${cmp}\n`;
txt += `${saldo>=0?'✅':'🔴'} Saldo: ${brl(saldo)}\n`;
if (Number(r.aporte)>0) txt += `📈 Aportes: ${brl(r.aporte)}\n`;
const top = r.top_cat||[];
if (top.length){ txt += `\n*Maiores categorias:*\n`; top.forEach(c => { txt += `• ${tc(c.categoria)}: ${brl(c.total)}\n`; }); }
if (r.maior && r.maior.descricao) txt += `\n*Maior gasto:* ${clean(r.maior.descricao)} — ${brl(r.maior.valor)}\n`;
txt += `\n_Resumo automático do mês que fechou._`;
return [{ json: { text: txt } }];
